package com.ensam.inventia.service.impl;
import com.ensam.inventia.dto.request.*; import com.ensam.inventia.dto.response.*; import com.ensam.inventia.entity.*; import com.ensam.inventia.enums.*; import com.ensam.inventia.exception.*; import com.ensam.inventia.mapper.EntityMapper; import com.ensam.inventia.repository.*; import com.ensam.inventia.security.JwtUtil; import com.ensam.inventia.service.*;
import jakarta.annotation.PostConstruct; import lombok.RequiredArgsConstructor; import org.apache.poi.xssf.usermodel.XSSFWorkbook; import com.itextpdf.kernel.pdf.*; import com.itextpdf.layout.*; import com.itextpdf.layout.element.Paragraph; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.data.domain.*; import org.springframework.security.authentication.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import software.amazon.awssdk.core.sync.*; import software.amazon.awssdk.services.s3.*; import software.amazon.awssdk.services.s3.model.*; import java.io.*; import java.time.*; import java.util.*; import java.util.stream.*;
class Current { static String email(){return SecurityContextHolder.getContext().getAuthentication().getName();} }
@Service @RequiredArgsConstructor @Transactional class AuthServiceImpl implements AuthService { private final UserRepository users; private final RoleRepository roles; private final PasswordEncoder encoder; private final AuthenticationManager auth; private final JwtUtil jwt; private final RefreshTokenServiceImpl refresh; private final EntityMapper mapper;
 public AuthResponse register(RegisterRequest r, jakarta.servlet.http.HttpServletResponse res){ if(users.existsByEmail(r.email())||users.existsByUsername(r.username())) throw new DuplicateResourceException("User already exists"); var role=roles.findByName(RoleEnum.ROLE_PARTICIPANT).orElseGet(()->roles.save(Role.builder().name(RoleEnum.ROLE_PARTICIPANT).build())); var u=User.builder().username(r.username()).email(r.email()).password(encoder.encode(r.password())).firstName(r.firstName()).lastName(r.lastName()).enabled(true).role(role).build(); users.save(u); var rt = refresh.create(u).getToken(); addCookie(res, rt, 7*24*3600); return new AuthResponse(jwt.generate(u.getEmail()), mapper.user(u));}
 public AuthResponse login(LoginRequest r, jakarta.servlet.http.HttpServletResponse res){ auth.authenticate(new UsernamePasswordAuthenticationToken(r.email(),r.password())); var u=users.findByEmail(r.email()).orElseThrow(); var rt = refresh.create(u).getToken(); addCookie(res, rt, 7*24*3600); return new AuthResponse(jwt.generate(u.getEmail()), mapper.user(u));}
 public AuthResponse refresh(String token, jakarta.servlet.http.HttpServletResponse res){ var t=refresh.verify(token); var rt = t.getToken(); addCookie(res, rt, 7*24*3600); return new AuthResponse(jwt.generate(t.getUser().getEmail()), mapper.user(t.getUser()));}
 public UserResponse me(){ return mapper.user(users.findByEmail(Current.email()).orElseThrow());}
 public void logout(String token, jakarta.servlet.http.HttpServletResponse res){ if(token != null) refresh.revoke(token); addCookie(res, "", 0);}
 private void addCookie(jakarta.servlet.http.HttpServletResponse res, String token, int maxAge) { jakarta.servlet.http.Cookie c = new jakarta.servlet.http.Cookie("refresh_token", token); c.setHttpOnly(true); c.setPath("/"); c.setMaxAge(maxAge); res.addCookie(c); }
}
@Service @RequiredArgsConstructor @Transactional class RefreshTokenServiceImpl implements RefreshTokenService { private final RefreshTokenRepository repo; @Value("${app.jwt.refresh-token-days}") private long days; RefreshToken create(User u){return repo.save(RefreshToken.builder().token(UUID.randomUUID().toString()).user(u).revoked(false).expiryDate(Instant.now().plus(Duration.ofDays(days))).build());} RefreshToken verify(String token){var t=repo.findByToken(token).orElseThrow(()->new BadRequestException("Invalid refresh token")); if(Boolean.TRUE.equals(t.getRevoked())||t.getExpiryDate().isBefore(Instant.now())) throw new BadRequestException("Refresh token expired"); return t;} void revoke(String token){repo.findByToken(token).ifPresent(t->{t.setRevoked(true); repo.save(t);});}}
@Service @RequiredArgsConstructor @Transactional class UserServiceImpl implements UserService { private final UserRepository users; private final RoleRepository roles; private final EntityMapper mapper; private final PasswordEncoder encoder; public UserResponse create(CreateUserRequest r){if(users.existsByEmail(r.email())||users.existsByUsername(r.username())) throw new DuplicateResourceException("User already exists"); if(r.role()==RoleEnum.ROLE_ADMIN) throw new BadRequestException("Cannot create admin user"); var role=roles.findByName(r.role()).orElseThrow(); var u=User.builder().username(r.username()).email(r.email()).password(encoder.encode(r.password())).firstName(r.firstName()).lastName(r.lastName()).enabled(true).role(role).build(); users.save(u); return mapper.user(u);} public PageResponse<UserResponse> list(Pageable p){return PageResponse.from(users.findAll(p).map(mapper::user));} public UserResponse get(Long id){return mapper.user(users.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found")));} public UserResponse update(Long id,UpdateProfileRequest r){var u=users.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found")); u.setFirstName(r.firstName()); u.setLastName(r.lastName()); u.setBio(r.bio()); users.save(u); return mapper.user(u);} public UserResponse roles(Long id,UpdateRoleRequest r){var u=users.findById(id).orElseThrow(); u.setRole(roles.findByName(RoleEnum.valueOf(r.role())).orElseThrow()); users.save(u); return mapper.user(u);} public void disable(Long id){var u=users.findById(id).orElseThrow(); if(u.getEmail().equals(Current.email())) throw new BadRequestException("Admin cannot deactivate own account"); u.setEnabled(false); users.save(u);} public void enable(Long id){var u=users.findById(id).orElseThrow(); u.setEnabled(true); users.save(u);}}
@Service @RequiredArgsConstructor @Transactional class HackathonServiceImpl implements HackathonService { private final HackathonRepository repo; private final UserRepository users; private final TeamMemberRepository teamMembers; private final EntityMapper mapper; public PageResponse<HackathonSummaryResponse> list(Pageable p){return PageResponse.from(repo.findAll(p).map(mapper::hackathonSummary));} public HackathonResponse get(Long id){return mapper.hackathon(repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Hackathon not found")));} public HackathonAnalyticsResponse analytics(Long id){var h=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Hackathon not found")); var u=users.findByEmail(Current.email()).orElseThrow(); if(u.getRole().getName()==RoleEnum.ROLE_MANAGER && !h.getCreatedBy().getId().equals(u.getId())) throw new UnauthorizedOperationException("Not allowed to view analytics for this hackathon"); long teams = h.getTeams().size(); long participants = h.getTeams().stream().mapToLong(t->t.getMembers().size()).sum(); long submissions = h.getTeams().stream().filter(t->t.getSubmission()!=null).count(); return new HackathonAnalyticsResponse(teams, participants, submissions);} public HackathonResponse create(HackathonRequest r){validate(r); var h=Hackathon.builder().title(r.title()).description(r.description()).theme(r.theme()).prize(r.prize()).registrationDeadline(r.registrationDeadline()).startDate(r.startDate()).endDate(r.endDate()).maxTeamSize(r.maxTeamSize()).createdBy(users.findByEmail(Current.email()).orElseThrow()).build(); h.computeStatus(); return mapper.hackathon(repo.save(h));} public HackathonResponse update(Long id,HackathonRequest r){validate(r); var h=repo.findById(id).orElseThrow(); h.setTitle(r.title()); h.setDescription(r.description()); h.setTheme(r.theme()); h.setPrize(r.prize()); h.setRegistrationDeadline(r.registrationDeadline()); h.setStartDate(r.startDate()); h.setEndDate(r.endDate()); h.setMaxTeamSize(r.maxTeamSize()); h.computeStatus(); return mapper.hackathon(h);} public void delete(Long id){repo.deleteById(id);} public TeamResponse myTeam(Long hackathonId){var u=users.findByEmail(Current.email()).orElseThrow(); var tm=teamMembers.findByUserIdAndTeamHackathonId(u.getId(),hackathonId).orElseThrow(()->new ResourceNotFoundException("Not in a team")); return mapper.team(tm.getTeam());} private void validate(HackathonRequest r){ if(r.endDate().isBefore(r.startDate())) throw new BadRequestException("endDate must be after startDate"); if(r.registrationDeadline().isAfter(r.startDate())) throw new BadRequestException("registrationDeadline must be before startDate");}}
@Service @RequiredArgsConstructor @Transactional class TeamServiceImpl implements TeamService { private final TeamRepository teams; private final HackathonRepository hacks; private final UserRepository users; private final TeamMemberRepository members; private final EntityMapper mapper; public TeamResponse create(Long hackathonId,TeamRequest r){var u=users.findByEmail(Current.email()).orElseThrow(); if(members.existsByUserIdAndTeamHackathonId(u.getId(),hackathonId)) throw new BadRequestException("User already has a team in this hackathon"); var h=hacks.findById(hackathonId).orElseThrow(); var t=Team.builder().name(r.name()).description(r.description()).techStack(r.techStack()).hackathon(h).build(); var m=TeamMember.builder().team(t).user(u).memberRole(TeamMemberRole.LEADER).build(); t.getMembers().add(m); return mapper.team(teams.save(t));} public TeamResponse get(Long id){return mapper.team(teams.findById(id).orElseThrow(()->new ResourceNotFoundException("Team not found")));} public TeamResponse add(Long id,AddMemberRequest r){var t=teams.findById(id).orElseThrow(); if(t.getMembers().size()>=t.getHackathon().getMaxTeamSize()) throw new TeamFullException("Team is full"); var u=users.findById(r.userId()).orElseThrow(); if(members.existsByUserIdAndTeamHackathonId(u.getId(),t.getHackathon().getId())) throw new BadRequestException("User already has a team in this hackathon"); t.getMembers().add(TeamMember.builder().team(t).user(u).memberRole(TeamMemberRole.MEMBER).build()); return mapper.team(t);} public TeamResponse join(JoinTeamRequest r){var t=teams.findByJoinCode(r.joinCode()).orElseThrow(()->new ResourceNotFoundException("Invalid join code")); if(t.getMembers().size()>=t.getHackathon().getMaxTeamSize()) throw new TeamFullException("Team is full"); var u=users.findByEmail(Current.email()).orElseThrow(); if(members.existsByUserIdAndTeamHackathonId(u.getId(),t.getHackathon().getId())) throw new BadRequestException("User already has a team in this hackathon"); t.getMembers().add(TeamMember.builder().team(t).user(u).memberRole(TeamMemberRole.MEMBER).build()); return mapper.team(teams.save(t));} public void delete(Long id){var t=teams.findById(id).orElseThrow(); var u=users.findByEmail(Current.email()).orElseThrow(); boolean isLeader=t.getMembers().stream().anyMatch(m->m.getUser().getId().equals(u.getId())&&m.getMemberRole()==TeamMemberRole.LEADER); if(u.getRole().getName()!=RoleEnum.ROLE_ADMIN && !isLeader) throw new UnauthorizedOperationException("Only leader can delete the team"); if(t.getSubmission()!=null) throw new BadRequestException("Team has a submission"); teams.delete(t);}}
@Service @RequiredArgsConstructor class ObjectStorageService { private final S3Client s3; @Value("${app.storage.bucket}") private String bucket; @Value("${app.storage.enabled:true}") private boolean enabled; @PostConstruct void init(){if(!enabled) return; try{s3.headBucket(HeadBucketRequest.builder().bucket(bucket).build());}catch(NoSuchBucketException e){s3.createBucket(CreateBucketRequest.builder().bucket(bucket).build());}catch(S3Exception e){if(e.statusCode()==404) s3.createBucket(CreateBucketRequest.builder().bucket(bucket).build()); else throw e;}} StoredObject storeZip(Long hackathonId, Long teamId, MultipartFile file){if(!enabled) throw new BadRequestException("Object storage is disabled"); String name=Optional.ofNullable(file.getOriginalFilename()).orElse("submission.zip"); if(file.isEmpty()) throw new BadRequestException("Submission ZIP is required"); if(!name.toLowerCase(Locale.ROOT).endsWith(".zip")) throw new BadRequestException("Submission file must be a .zip archive"); String key="hackathons/%d/teams/%d/%s-%s".formatted(hackathonId,teamId,UUID.randomUUID(),name.replaceAll("[^A-Za-z0-9._-]","_")); try{ s3.putObject(PutObjectRequest.builder().bucket(bucket).key(key).contentType("application/zip").contentLength(file.getSize()).build(), RequestBody.fromInputStream(file.getInputStream(), file.getSize())); return new StoredObject(key,name,file.getSize()); }catch(IOException e){throw new BadRequestException("Could not read ZIP file");}catch(Exception e){throw new BadRequestException("Could not store ZIP in MinIO");}} ByteArrayResource get(String key){if(!enabled) throw new BadRequestException("Object storage is disabled"); try{var bytes=s3.getObject(GetObjectRequest.builder().bucket(bucket).key(key).build(), ResponseTransformer.toBytes()).asByteArray(); return new ByteArrayResource(bytes);}catch(Exception e){throw new ResourceNotFoundException("Submission artifact not found");}} void delete(String key){if(enabled&&key!=null&&!key.isBlank()) try{s3.deleteObject(DeleteObjectRequest.builder().bucket(bucket).key(key).build());}catch(Exception ignored){}} record StoredObject(String key,String fileName,Long size){} }
@Service @RequiredArgsConstructor @Transactional class SubmissionServiceImpl implements SubmissionService { private final TeamRepository teams; private final SubmissionRepository submissions; private final UserRepository users; private final EntityMapper mapper; private final ObjectStorageService storage; public SubmissionResponse upsert(Long teamId,SubmissionRequest r,MultipartFile file){var t=teams.findById(teamId).orElseThrow(); var u=users.findByEmail(Current.email()).orElseThrow(); boolean isMember=t.getMembers().stream().anyMatch(m->m.getUser().getId().equals(u.getId())); if(!isMember && u.getRole().getName()!=RoleEnum.ROLE_ADMIN) throw new UnauthorizedOperationException("Only team members can submit"); if(LocalDate.now().isAfter(t.getHackathon().getEndDate())) throw new DeadlinePassedException("Submission deadline passed"); var existing=submissions.findByTeamId(teamId); var s=existing.orElse(Submission.builder().team(t).build()); if(file==null||file.isEmpty()){ if(existing.isEmpty()) throw new BadRequestException("Submission ZIP is required"); } else { var stored=storage.storeZip(t.getHackathon().getId(),teamId,file); storage.delete(s.getArtifactObjectKey()); s.setArtifactObjectKey(stored.key()); s.setArtifactFileName(stored.fileName()); s.setArtifactSize(stored.size()); } s.setTitle(r.title()); s.setDescription(r.description()); s.setRepositoryUrl(r.repositoryUrl()); s.setDemoUrl(r.demoUrl()); s.setTechStack(r.techStack()); return mapper.submission(submissions.save(s));} public SubmissionResponse get(Long teamId){return mapper.submission(submissions.findByTeamId(teamId).orElseThrow(()->new ResourceNotFoundException("Submission not found")));} public SubmissionDownload download(Long teamId){var s=submissions.findByTeamId(teamId).orElseThrow(()->new ResourceNotFoundException("Submission not found")); authorizeTeamAccess(s.getTeam()); return new SubmissionDownload(storage.get(s.getArtifactObjectKey()),s.getArtifactFileName());} public void delete(Long teamId){var t=teams.findById(teamId).orElseThrow(); var u=users.findByEmail(Current.email()).orElseThrow(); boolean isLeader=t.getMembers().stream().anyMatch(m->m.getUser().getId().equals(u.getId())&&m.getMemberRole()==TeamMemberRole.LEADER); if(u.getRole().getName()!=RoleEnum.ROLE_ADMIN && !isLeader) throw new UnauthorizedOperationException("Only leader can delete the submission"); submissions.findByTeamId(teamId).ifPresent(s->{storage.delete(s.getArtifactObjectKey()); t.setSubmission(null); submissions.delete(s); submissions.flush();});} private void authorizeTeamAccess(Team t){var u=users.findByEmail(Current.email()).orElseThrow(); boolean isMember=t.getMembers().stream().anyMatch(m->m.getUser().getId().equals(u.getId())); if(!isMember && u.getRole().getName()!=RoleEnum.ROLE_MANAGER && u.getRole().getName()!=RoleEnum.ROLE_ADMIN) throw new UnauthorizedOperationException("Not allowed to download this submission");} record SubmissionDownload(ByteArrayResource body,String fileName){} }
@Service @RequiredArgsConstructor @Transactional class ScoreServiceImpl implements ScoreService { private final SubmissionRepository submissions; private final ScoreRepository scores; private final UserRepository users; private final EntityMapper mapper; public ScoreResponse score(Long submissionId,ScoreRequest r){var judge=users.findByEmail(Current.email()).orElseThrow(); if(scores.existsBySubmissionIdAndJudgeId(submissionId,judge.getId())) throw new DuplicateScoreException("Judge already scored this submission"); var s=Score.builder().submission(submissions.findById(submissionId).orElseThrow()).judge(judge).technicalScore(r.technicalScore()).creativityScore(r.creativityScore()).presentationScore(r.presentationScore()).comment(r.comment()).build(); s.calculate(); return mapper.score(scores.save(s));} public List<ScoreResponse> list(Long submissionId){return scores.findBySubmissionId(submissionId).stream().map(mapper::score).toList();}}
@Service @RequiredArgsConstructor @Transactional(readOnly=true) class DashboardServiceImpl implements DashboardService { private final UserRepository users; private final HackathonRepository hacks; private final TeamRepository teams; private final SubmissionRepository submissions; private final ScoreRepository scores; public DashboardStatsResponse stats(){return new DashboardStatsResponse(users.count(),hacks.count(),teams.count(),submissions.count(),scores.count(),Map.of("users",users.count(),"hackathons",hacks.count(),"teams",teams.count()));}}
@Service @RequiredArgsConstructor @Transactional(readOnly=true) class ExportServiceImpl implements ExportService { private final TeamRepository teams; public byte[] pdf(Long hackathonId){try(var out=new ByteArrayOutputStream(); var writer=new PdfWriter(out); var pdf=new PdfDocument(writer); var doc=new Document(pdf)){doc.add(new Paragraph("InventIA Leaderboard")); teams.findAll().stream().filter(t->t.getHackathon().getId().equals(hackathonId)).forEach(t->doc.add(new Paragraph(t.getName()))); doc.close(); return out.toByteArray();}catch(Exception e){throw new BadRequestException("PDF export failed");}} public byte[] excel(Long hackathonId){try(var wb=new XSSFWorkbook(); var out=new ByteArrayOutputStream()){var sh=wb.createSheet("Participants"); var row=sh.createRow(0); row.createCell(0).setCellValue("Team"); row.createCell(1).setCellValue("Member"); int[] i={1}; teams.findAll().stream().filter(t->t.getHackathon().getId().equals(hackathonId)).forEach(t->t.getMembers().forEach(m->{var r=sh.createRow(i[0]++); r.createCell(0).setCellValue(t.getName()); r.createCell(1).setCellValue(m.getUser().getEmail());})); wb.write(out); return out.toByteArray();}catch(Exception e){throw new BadRequestException("Excel export failed");}}}
@Service @RequiredArgsConstructor @Transactional class ChatServiceImpl implements ChatService { private final ChatMessageRepository messages; private final TeamRepository teams; private final UserRepository users; private final EntityMapper mapper; public List<ChatMessageResponse> list(Long teamId){var t=teams.findById(teamId).orElseThrow(); var u=users.findByEmail(Current.email()).orElseThrow(); boolean isMember=t.getMembers().stream().anyMatch(m->m.getUser().getId().equals(u.getId())); if(!isMember && u.getRole().getName()!=RoleEnum.ROLE_ADMIN) throw new UnauthorizedOperationException("Only members can view chat"); return messages.findByTeamIdOrderByCreatedAtAsc(teamId).stream().map(mapper::chatMessage).toList();} public ChatMessageResponse send(Long teamId, ChatMessageRequest r){var t=teams.findById(teamId).orElseThrow(); var u=users.findByEmail(Current.email()).orElseThrow(); boolean isMember=t.getMembers().stream().anyMatch(m->m.getUser().getId().equals(u.getId())); if(!isMember) throw new UnauthorizedOperationException("Only members can send messages"); var m=ChatMessage.builder().team(t).sender(u).content(r.content()).build(); return mapper.chatMessage(messages.save(m));}}
